777	+import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
778	+import path from "node:path";
779	+import type { State } from "../domain/types.ts";
780	+
781	+export interface Repository {
782	+  mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R>;
783	+}
784	+
785	+function emptyState(): State {
786	+  return { tools: [], loans: [] };
787	+}
788	+
789	+async function readExistingState(dataFilePath: string): Promise<State | null> {
790	+  let raw: string;
791	+  try {
792	+    raw = await readFile(dataFilePath, "utf8");
793	+  } catch (err) {
794	+    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
795	+      return null;
796	+    }
797	+    throw err;
798	+  }
799	+  if (raw.trim().length === 0) {
800	+    return null;
801	+  }
802	+  return JSON.parse(raw) as State;
803	+}
804	+
805	+async function writeStateAtomically(dataFilePath: string, state: State): Promise<void> {
806	+  const dir = path.dirname(dataFilePath);
807	+  await mkdir(dir, { recursive: true });
808	+  const tempFilePath = path.join(dir, `.${path.basename(dataFilePath)}.${process.pid}.${Date.now()}.tmp`);
809	+  await writeFile(tempFilePath, JSON.stringify(state, null, 2), "utf8");
810	+  await rename(tempFilePath, dataFilePath);
811	+}
812	+
813	+export async function createRepository(dataFilePath: string): Promise<Repository> {
814	+  const existingState = await readExistingState(dataFilePath);
815	+  let state: State = existingState ?? emptyState();
816	+
817	+  if (existingState === null) {
818	+    await writeStateAtomically(dataFilePath, state);
819	+  }
820	+
821	+  // Serializes mutate() calls: each call is chained onto the previous one,
822	+  // so read -> decide -> write per call runs atomically with respect to others (AD-3).
823	+  let queue: Promise<unknown> = Promise.resolve();
824	+
825	+  function mutate<R>(fn: (state: State) => { state: State; result: R }): Promise<R> {
826	+    const task = queue.then(async () => {
827	+      const { state: nextState, result } = fn(state);
828	+      await writeStateAtomically(dataFilePath, nextState);
829	+      state = nextState;
830	+      return result;
831	+    });
832	+    queue = task.catch(() => {});
833	+    return task;
834	+  }
835	+
836	+  return { mutate };
837	+}
