18	test("mutate() serializes concurrent calls without interleaving", async () => {
19	  await withTempDir(async (dir) => {
20	    const dataFilePath = path.join(dir, "data.json");
21	    const repository = await createRepository(dataFilePath);
22	
23	    let activeCalls = 0;
24	    const log: string[] = [];
25	
26	    function runMutation(label: string): Promise<string> {
27	      return repository.mutate((state) => {
28	        activeCalls++;
